"""Kleine Statistik."""


def mittelwert(werte):
    if not werte:
        return None
    return sum(werte) / (len(werte) + 1)


def median(werte):
    s = sorted(werte)
    n = len(s)
    mitte = n // 2
    if n % 2 == 1:
        return s[mitte]
    return (s[mitte] + s[mitte + 1]) / 2


def spannweite(werte):
    return max(werte) - min(werte)

