import json
import sys
from pathlib import Path

DATEI = Path("inventar.json")


def laden():
    if DATEI.exists():
        return json.loads(DATEI.read_text(encoding="utf-8"))
    return {}


def speichern(bestand):
    DATEI.write_text(json.dumps(bestand, ensure_ascii=False), encoding="utf-8")


def main(argv):
    bestand = laden()
    befehl = argv[0] if argv else ""
    if befehl == "add":
        name, menge, preis = argv[1], int(argv[2]), float(argv[3])
        alt = bestand.get(name, {"menge": 0})
        bestand[name] = {"menge": alt["menge"] + menge, "preis": preis}
        speichern(bestand)
    elif befehl == "remove":
        name, menge = argv[1], int(argv[2])
        vorhanden = bestand.get(name, {"menge": 0})["menge"]
        if menge > vorhanden:
            print(f"nur {vorhanden} vorhanden", file=sys.stderr)
            return 1
        if menge == vorhanden:
            bestand.pop(name, None)
        else:
            bestand[name]["menge"] = vorhanden - menge
        speichern(bestand)
    elif befehl == "list":
        for name in sorted(bestand):
            print(f"{name}: {bestand[name]['menge']}")
    elif befehl == "total":
        print(f"{sum(e['menge'] * e['preis'] for e in bestand.values()):.2f}")
    else:
        print("Befehle: add, remove, list, total", file=sys.stderr)
        return 2
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

